/**
 * ZDola Auto Video Downloader — Content Script (Isolated World)
 * Strictly connects with MAIN-world extractor (extractor.js) for 100% Watermark-Free raw streams.
 * Eliminates duplicate downloads & prevents watermarked DOM fallbacks.
 */
(() => {
  'use strict';

  console.log('[ZDola Downloader Bridge] Content script active on:', window.location.href);

  // In-memory deduplication set
  const downloadedMediaKeys = new Set();
  let latestExtractedVideos = [];

  function showDownloadToast(title, resolution = '1080P Raw (No Watermark)') {
    try {
      const existing = document.getElementById('zdola-auto-toast');
      if (existing) existing.remove();

      const toast = document.createElement('div');
      toast.id = 'zdola-auto-toast';
      toast.style.cssText = `
        position: fixed;
        bottom: 24px;
        right: 24px;
        z-index: 9999999;
        background: linear-gradient(135deg, #18181b 0%, #09090b 100%);
        border: 1px solid rgba(168, 85, 247, 0.7);
        box-shadow: 0 10px 30px rgba(0, 0, 0, 0.8), 0 0 25px rgba(168, 85, 247, 0.4);
        color: #f3f4f6;
        padding: 12px 18px;
        border-radius: 12px;
        font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
        font-size: 13px;
        display: flex;
        align-items: center;
        gap: 12px;
        animation: zdolaSlideIn 0.3s cubic-bezier(0.16, 1, 0.3, 1);
        pointer-events: none;
      `;

      toast.innerHTML = `
        <div style="width: 36px; height: 36px; border-radius: 8px; background: linear-gradient(135deg, #7c3aed 0%, #a855f7 100%); display: flex; align-items: center; justify-content: center; font-size: 18px; flex-shrink: 0; box-shadow: 0 0 14px rgba(168,85,247,0.5);">
          📥
        </div>
        <div style="display: flex; flex-direction: column; gap: 2px;">
          <strong style="color: #fff; font-weight: 600; display: flex; align-items: center; gap: 6px;">
            Watermark-Free Video Downloaded!
            <span style="background: rgba(52, 211, 153, 0.2); color: #34d399; padding: 1px 6px; border-radius: 4px; font-size: 10px; font-weight: 700; border: 1px solid rgba(52, 211, 153, 0.4);">${resolution}</span>
          </strong>
          <span style="color: #9ca3af; font-size: 11px; max-width: 300px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${escapeHtml(title || 'Saved to Downloads/ZDola_Videos')}</span>
        </div>
      `;

      if (!document.getElementById('zdola-toast-style')) {
        const style = document.createElement('style');
        style.id = 'zdola-toast-style';
        style.textContent = `
          @keyframes zdolaSlideIn {
            from { transform: translateY(30px) scale(0.95); opacity: 0; }
            to { transform: translateY(0) scale(1); opacity: 1; }
          }
        `;
        document.head.appendChild(style);
      }

      document.body.appendChild(toast);

      setTimeout(() => {
        toast.style.transition = 'opacity 0.4s ease, transform 0.4s ease';
        toast.style.opacity = '0';
        toast.style.transform = 'translateY(15px)';
        setTimeout(() => toast.remove(), 400);
      }, 4500);
    } catch {}
  }

  function escapeHtml(str) {
    return String(str || '').replace(/[&<>"']/g, c => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    }[c]));
  }

  function triggerDownload(video, force = false) {
    if (!video || !video.url) return;
    
    // STRICT RULE: Only unwatermarked fallback_api streams are downloaded!
    if (video.source !== 'fallback_api' && !force) {
      console.log('[ZDola Downloader] Ignored non-fallback preview video stream.');
      return;
    }

    const cleanUrl = String(video.url).trim();
    if (!cleanUrl.startsWith('http')) return;

    const mediaKey = String(video.vid || cleanUrl);
    if (!force && downloadedMediaKeys.has(mediaKey)) {
      return;
    }
    downloadedMediaKeys.add(mediaKey);

    chrome.runtime.sendMessage({
      type: 'AUTO_DOWNLOAD_VIDEO',
      force,
      video: {
        ...video,
        url: cleanUrl,
        pageUrl: window.location.href,
        prompt: video.prompt || video.topicTitle || video.title || ''
      }
    }, response => {
      if (response?.ok && response?.downloaded) {
        showDownloadToast(video.prompt || video.topicTitle || video.title || 'ZDola Video', '1080P Raw (No Watermark)');
      }
    });
  }

  function requestMainWorldMedia(timeoutMs = 1500) {
    return new Promise(resolve => {
      let settled = false;
      const onResponse = event => {
        if (settled) return;
        settled = true;
        window.removeEventListener('DOLA_CHAT_MEDIA_RESPONSE', onResponse);
        const videos = event?.detail?.videos || [];
        latestExtractedVideos = videos;
        resolve(videos);
      };
      window.addEventListener('DOLA_CHAT_MEDIA_RESPONSE', onResponse, { once: true });
      window.dispatchEvent(new CustomEvent('DOLA_GET_CHAT_MEDIA'));
      setTimeout(() => {
        if (!settled) {
          settled = true;
          window.removeEventListener('DOLA_CHAT_MEDIA_RESPONSE', onResponse);
          resolve(latestExtractedVideos);
        }
      }, timeoutMs);
    });
  }

  // 1. Listen for new unwatermarked video extractions from extractor.js
  window.addEventListener('DOLA_VIDEO_EXTRACTED', event => {
    const video = event.detail;
    if (video && video.url) {
      console.log('[ZDola Downloader] Extracted unwatermarked video stream:', video);
      triggerDownload(video);
    }
  });

  // 2. Direct Prompt Injection Engine
  function injectDolaPrompt(promptText, targetRatio = '9:16') {
    return new Promise((resolve) => {
      try {
        const textarea = document.querySelector(
          'textarea.semi-input-textarea, textarea, div[contenteditable="true"], div[data-slate-editor="true"], [role="textbox"]'
        );

        if (!textarea) {
          return resolve({ ok: false, error: 'Composer textarea not found' });
        }

        textarea.focus();
        if (textarea.tagName === 'DIV' || textarea.isContentEditable) {
          textarea.innerText = promptText;
        } else {
          textarea.value = promptText;
        }

        textarea.dispatchEvent(new Event('input', { bubbles: true }));
        textarea.dispatchEvent(new Event('change', { bubbles: true }));

        // Notify inject.js / extractor.js of ratio & 30s settings
        window.postMessage({
          type: 'PURZA_UPDATE_SETTINGS',
          ratio: targetRatio,
          duration: 30
        }, '*');

        // Click send button
        setTimeout(() => {
          const sendBtn = document.querySelector(
            'button[type="submit"], [data-testid="chat_input_send_button"], div[role="button"][class*="send"], button[class*="send"], svg[class*="send"]'
          )?.closest('button, div[role="button"]');

          if (sendBtn && !sendBtn.disabled) {
            sendBtn.click();
            resolve({ ok: true, success: true, prompt: promptText });
          } else {
            // Fallback Enter key
            textarea.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, bubbles: true }));
            resolve({ ok: true, success: true, fallbackEnter: true, prompt: promptText });
          }
        }, 350);
      } catch (err) {
        resolve({ ok: false, error: err.message || String(err) });
      }
    });
  }

  // 3. Quota Limit Detection (Network + DOM MutationObserver)
  let lastQuotaDetectedTime = 0;
  function reportQuotaExhausted(reason = 'Dola Generation Limit Reached') {
    const now = Date.now();
    if (now - lastQuotaDetectedTime < 10000) return; // Debounce 10s
    lastQuotaDetectedTime = now;

    console.warn('[ZDola Quota Guard] ⚠️ Generation limit detected:', reason);
    chrome.runtime.sendMessage({
      action: 'DOLA_QUOTA_DETECTED',
      type: 'DOLA_QUOTA_DETECTED',
      reason
    }).catch(() => {});
  }

  window.addEventListener('DOLA_QUOTA_EXHAUSTED', (event) => {
    reportQuotaExhausted(event.detail?.reason || 'API 429 Quota Exceeded');
  });

  // Observe DOM for Quota Warning Toasts
  const quotaRegex = /reached.*daily.*limit|daily.*limit.*reached|exceeded.*limit|quota.*exceeded|đạt giới hạn|hết lượt|达到今日|上限|次数已用尽|今日额度/i;
  const quotaObserver = new MutationObserver((mutations) => {
    for (const m of mutations) {
      for (const node of m.addedNodes) {
        if (node.nodeType === Node.ELEMENT_NODE) {
          const text = node.innerText || node.textContent || '';
          if (text.length > 5 && text.length < 300 && quotaRegex.test(text)) {
            reportQuotaExhausted(`DOM Toast: ${text.trim()}`);
            return;
          }
        }
      }
    }
  });

  if (document.body) {
    quotaObserver.observe(document.body, { childList: true, subtree: true });
  } else {
    document.addEventListener('DOMContentLoaded', () => {
      quotaObserver.observe(document.body, { childList: true, subtree: true });
    });
  }

  // 4. Runtime Message Listener
  chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
    if (!message) return false;

    if (message.type === 'INJECT_DOLA_TASK') {
      injectDolaPrompt(message.prompt, message.ratio || '9:16').then(sendResponse);
      return true;
    }

    if (message.type === 'SCAN_AND_DOWNLOAD_ACTIVE_TAB') {
      (async () => {
        try {
          const videos = await requestMainWorldMedia(2000);
          const unwatermarked = videos.filter(v => v?.source === 'fallback_api' && v.url);

          if (unwatermarked.length > 0) {
            const target = unwatermarked[unwatermarked.length - 1];
            triggerDownload(target, true);
            sendResponse({ ok: true, foundCount: 1, unwatermarked: true, url: target.url });
            return;
          }

          sendResponse({ ok: false, foundCount: 0, message: 'Generating or unwatermarked 1080P stream not ready yet.' });
        } catch (err) {
          sendResponse({ ok: false, error: err.message || String(err) });
        }
      })();
      return true;
    }
  });

})();
